SELECT CASE WHEN st.sqft >= 13919 THEN 'high' WHEN st.sqft >= 2520 THEN 'mid' ELSE 'low' END AS sqft_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(s.carrier))) AS carrier_values, COUNT(DISTINCT s.cost) AS unique_orders FROM shipments s INNER JOIN orders o ON s.order_id = o.id LEFT JOIN stores st ON st.id = o.store_id GROUP BY CASE WHEN st.sqft >= 13919 THEN 'high' WHEN st.sqft >= 2520 THEN 'mid' ELSE 'low' END ORDER BY carrier_values DESC;
